// Components/SolxceLogoView.swift
import SwiftUI

/// Solxce official logo asset helper and view
public enum SolxceLogoAsset {
    public static let rawBase64: String = ""

    public static let sharedImage: UIImage? = {
        guard let data = Data(base64Encoded: rawBase64) else {
            return UIImage(named: "AppLogo") ?? UIImage(named: "CustomEmblemLogo")
        }
        return UIImage(data: data) ?? UIImage(named: "AppLogo")
    }()
}

/// Solxce brand logo mark rendering the official kinetic wing/spiky swoosh emblem
public struct SolxceLogoView: View {
    public var size: CGFloat = 64
    public var tint: Color? = nil
    public var showGlow: Bool = false
    public var showAppIconContainer: Bool = false

    public init(size: CGFloat = 64, tint: Color? = nil, showGlow: Bool = false, showAppIconContainer: Bool = false) {
        self.size = size
        self.tint = tint
        self.showGlow = showGlow
        self.showAppIconContainer = showAppIconContainer
    }

    public var body: some View {
        if showAppIconContainer {
            ZStack {
                // App Icon Obsidian Rounded Container
                RoundedRectangle(cornerRadius: size * 0.22, style: .continuous)
                    .fill(
                        LinearGradient(
                            colors: [
                                Color(red: 0.08, green: 0.08, blue: 0.08),
                                Color(red: 0.0, green: 0.0, blue: 0.0)
                            ],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: size * 0.22, style: .continuous)
                            .strokeBorder(
                                LinearGradient(
                                    colors: [
                                        Color.white.opacity(0.3),
                                        Color.white.opacity(0.05),
                                        Color.clear
                                    ],
                                    startPoint: .topLeading,
                                    endPoint: .bottomTrailing
                                ),
                                lineWidth: max(1, size * 0.015)
                            )
                    )
                    .shadow(color: Color.black.opacity(0.7), radius: size * 0.15, x: 0, y: size * 0.08)

                logoContent
                    .frame(width: size * 0.82, height: size * 0.82)
            }
            .frame(width: size, height: size)
        } else {
            logoContent
                .frame(width: size, height: size * 0.45)
        }
    }

    @ViewBuilder
    private var logoContent: some View {
        ZStack {
            if showGlow {
                Circle()
                    .fill(
                        RadialGradient(
                            colors: [
                                Color.white.opacity(0.3),
                                Color.white.opacity(0.05),
                                Color.clear
                            ],
                            center: .center,
                            startRadius: 0,
                            endRadius: size * 0.6
                        )
                    )
                    .blur(radius: size * 0.1)
            }

            if let uiImage = SolxceLogoAsset.sharedImage {
                if let tint = tint {
                    Image(uiImage: uiImage)
                        .resizable()
                        .renderingMode(.template)
                        .scaledToFit()
                        .foregroundColor(tint)
                } else {
                    Image(uiImage: uiImage)
                        .resizable()
                        .renderingMode(.template)
                        .scaledToFit()
                        .foregroundColor(AppTheme.text)
                }
            } else if let assetImage = UIImage(named: "AppLogo") {
                Image(uiImage: assetImage)
                    .resizable()
                    .renderingMode(.template)
                    .scaledToFit()
                    .foregroundColor(tint ?? AppTheme.text)
            } else {
                Image(systemName: "sparkle")
                    .resizable()
                    .scaledToFit()
                    .foregroundColor(tint ?? .white)
            }
        }
    }
}
